// Yahoo market context for the allocation dashboard; separate from reference returns.
const MB_SYMBOLS=[{key:'spy',symbol:'SPY',label:'SPY',unit:'USD',kind:'price'},{key:'brent',symbol:'BZ=F',label:'Brent front-month futures',unit:'USD/barrel',kind:'price'},{key:'treasury10y',symbol:'^TNX',label:'US 10-year Treasury yield',unit:'%',kind:'yield'}];
function mbDay(seconds,zone){return new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(seconds*1000));}
function mbPlans(c,now=Date.now()){if(!['collect','portfolio'].includes(c.action))return [];return MB_SYMBOLS.filter(p=>{const r=c.state.Meta['market_backdrop_'+p.key];return !r?.last_attempt_at||now-Date.parse(r.last_attempt_at)>=15*60000;});}
function mbParse(response,plan,now=Date.now()){
 if(response.error||response.statusCode>=400)throw Error('Yahoo quote unavailable');let data=response.body??response.data??response.response??response;if(typeof data==='string')data=JSON.parse(data);if(data.chart?.error)throw Error('Yahoo chart error');const r=data.chart?.result?.[0],meta=r?.meta;if(!meta||meta.symbol!==plan.symbol||!meta.exchangeTimezoneName)throw Error('Yahoo quote identity/timezone missing');
 if(plan.kind==='price'&&meta.currency!=='USD')throw Error('Unexpected quote currency');
 const price=meta.regularMarketPrice,previous=meta.previousClose,time=meta.regularMarketTime;
 if(Number.isFinite(price)&&price>0&&Number.isFinite(previous)&&previous>0&&Number.isFinite(time)&&time*1000<=now+300000&&now-time*1000<=6*86400000){if(plan.kind==='yield'&&price>30)throw Error('Unexpected Treasury yield units');const session=mbDay(time,meta.exchangeTimezoneName),delta=price-previous;return {...plan,value:price,previous_close:previous,change:delta,change_percent:plan.kind==='price'?delta/previous*100:null,change_bps:plan.kind==='yield'?delta*100:null,session,previous_session:'previous session',comparison_basis:'Yahoo explicit previousClose',exchange_timezone:meta.exchangeTimezoneName,quote_time:new Date(time*1000).toISOString(),session_state:session===mbDay(now/1000,meta.exchangeTimezoneName)?'current-session snapshot; may be delayed':'latest available session',checked_at:new Date(now).toISOString(),last_attempt_at:new Date(now).toISOString(),status:'ok',source_url:'https://finance.yahoo.com/quote/'+encodeURIComponent(plan.symbol)+'/'};}
 const closes=r.indicators?.quote?.[0]?.close,points=(r.timestamp||[]).map((t,i)=>({time:t,value:closes?.[i]})).filter(p=>Number.isFinite(p.value)&&p.value>0&&p.time*1000<=now+300000).sort((a,b)=>a.time-b.time);
 if(points.length<2)throw Error('No paired daily quote bars');const current=points.at(-1),prior=points.at(-2),session=mbDay(current.time,meta.exchangeTimezoneName),previous_session=mbDay(prior.time,meta.exchangeTimezoneName);
 if(session===previous_session)throw Error('Daily quote sessions not distinct');if(now-current.time*1000>6*86400000)throw Error('Yahoo quote stale');if(plan.kind==='yield'&&current.value>30)throw Error('Unexpected Treasury yield units');
 const delta=current.value-prior.value;return {...plan,value:current.value,previous_close:prior.value,change:delta,change_percent:plan.kind==='price'?delta/prior.value*100:null,change_bps:plan.kind==='yield'?delta*100:null,session,previous_session,exchange_timezone:meta.exchangeTimezoneName,quote_time:meta.regularMarketTime?new Date(meta.regularMarketTime*1000).toISOString():new Date(current.time*1000).toISOString(),session_state:session===mbDay(now/1000,meta.exchangeTimezoneName)?'current-session snapshot; may be delayed':'latest available session',checked_at:new Date(now).toISOString(),last_attempt_at:new Date(now).toISOString(),status:'ok',source_url:'https://finance.yahoo.com/quote/'+encodeURIComponent(plan.symbol)+'/'};
}
function mbApply(c,responses,plans,now=Date.now()){if(responses.length!==plans.length)throw Error('Market backdrop response count mismatch');for(let i=0;i<plans.length;i++){const plan=plans[i],key='market_backdrop_'+plan.key;let value;try{value={kind:'market_backdrop',...mbParse(responses[i],plan,now),instrument_kind:plan.kind};value.kind='market_backdrop';}catch{value={...(c.state.Meta[key]||plan),kind:'market_backdrop',instrument_kind:plan.kind,status:'unavailable',stale:true,last_attempt_at:new Date(now).toISOString()};}c.state.Meta[key]=value;c.dirty.push({table:'Meta',key,value});}c.operation='write';return c;}
function mbDashboard(c){const lines=['MARKET SNAPSHOT · YAHOO'],sign=(n,d=2)=>(n>=0?'+':'')+n.toFixed(d);for(const p of MB_SYMBOLS){const r=c.state.Meta?.['market_backdrop_'+p.key];if(!r||!Number.isFinite(r.value)){lines.push(p.label+': unavailable');continue;}const stale=r.status!=='ok'||Date.now()-Date.parse(r.checked_at)>3600000;lines.push(p.label+': '+r.value.toFixed(p.kind==='yield'?3:2)+' '+p.unit+' · '+(p.kind==='yield'?sign(r.change_bps,1)+' bp':sign(r.change_percent)+'%'),'Session '+r.session+' vs '+r.previous_session+' close · '+r.session_state,'Quote '+r.quote_time+(stale?' · STALE / refresh unavailable':''));}lines.push('Brent is a futures contract, not spot oil. Yield changes are basis points, not bond returns. SPY move excludes cash dividends; this is not portfolio P&L.');return lines.join('\n');}

